package cn.zhuatech.mdm.deep;import cn.zhuatech.mdm.common.ApiResponse;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/mdm-ops") public class DeepMasterDataController{private final DeepMasterDataService s;public DeepMasterDataController(DeepMasterDataService x){s=x;}@GetMapping("/workspace")ApiResponse<?> workspace(){return ApiResponse.ok(s.workspace());}@PostMapping("/domains/{id}/records")ApiResponse<?> ingest(@PathVariable Long id,@RequestBody DeepMasterDataService.RecordInput x){return ApiResponse.ok(s.ingest(id,x));}@PostMapping("/records/{id}/submit")ApiResponse<?> submit(@PathVariable Long id){return ApiResponse.ok(s.submit(id));}@PostMapping("/changes")ApiResponse<?> change(@RequestBody DeepMasterDataService.ChangeInput x){return ApiResponse.ok(s.requestChange(x));}}
